import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2017-FEB-15 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-FEB-15 :: Ceph Performance Weekly","date":"2017-02-17T00:00:00.000Z","updated":"2017-02-18T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","CRUSH算法","高可用性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-FEB-15_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-FEB-15_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),n={name:"posts/2017/2017-FEB-15_-_-_Ceph_Performance_Weekly.md"};function l(g,t,i,a,p,_){return r(),o("div",null,[...t[0]||(t[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Jeanne、Nick、Sage、Igor、Jaime、Ernesto 等</p><p><strong>会议内容</strong>：</p><p><strong>一、本周工作进展</strong></p><ul><li><strong>Sage</strong>： 对快速调度代码进行了拆分，成功移除了一些代码，有望提升性能。</li><li><strong>Igor</strong>： 正在研究减少镜像使用，以降低存储开销。</li><li><strong>Jaime</strong>： 发现Ceph存储集群在快照删除时存在延迟问题。</li><li><strong>Ernesto</strong>： 发现Ceph存储集群内存使用过高，可能是缓存配置问题。</li></ul><p><strong>二、主要议题</strong></p><ol><li><strong>快照删除延迟问题</strong>： <ul><li><strong>原因</strong>： 快照在删除时进行trim操作，导致IO性能下降。</li><li><strong>解决方案</strong>： 降低快照trim操作的并发度，调整相关参数，考虑使用Lucifer优化快照删除性能。</li></ul></li><li><strong>Ceph存储集群内存使用过高</strong>： <ul><li><strong>原因</strong>： 可能是缓存配置问题或程序bug。</li><li><strong>解决方案</strong>： 调整缓存大小，使用<code>mem_cache_debug</code>参数进行调试。</li></ul></li><li><strong>FastDispatch优化</strong>： <ul><li><strong>目标</strong>： 提升Ceph存储集群的性能。</li><li><strong>方案</strong>： 优化get reserved maps和release maps调用，优化FastDispatch代码，审计OSD中等待maps的代码。</li></ul></li></ol><p><strong>三、后续行动计划</strong></p><ul><li><strong>Sage</strong>： 继续优化快速调度代码。</li><li><strong>Igor</strong>： 继续研究减少镜像使用。</li><li><strong>Jaime</strong>： 继续测试Ceph存储集群，并优化快照删除性能。</li><li><strong>Ernesto</strong>： 调整缓存大小，并找出内存使用过高的原因。</li><li><strong>所有人员</strong>： 优化FastDispatch代码，并审计OSD中等待maps的代码。</li></ul><p><strong>四、其他</strong></p><ul><li>会议中还讨论了Ceph存储集群的日志性能、BlueStore缓存、缓存驱逐策略等问题。</li></ul><p><strong>五、总结</strong></p><p>本周Ceph存储集群的开发工作主要集中在性能优化和bug修复方面。下周将继续推进相关工作，并关注新的问题和挑战。</p>',15)])])}const u=e(n,[["render",l]]);export{m as __pageData,u as default};
